using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class IncidentState:Entity<short>{private IncidentState(){}private IncidentState(short id,string code,string name,bool terminal){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));Id=id;Code=OperationRules.Text(code,40);Name=OperationRules.Text(name,100);IsTerminal=terminal;IsActive=true;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public bool IsTerminal{get;private set;}public bool IsActive{get;private set;}public static IncidentState Create(short id,string code,string name,bool terminal=false)=>new(id,code,name,terminal);}
